self.onInit = function () {
    var NULL_UUID = '13814000-1dd2-11b2-8080-808080808080';

        // styles of the dynamically created elements (the template CSS does not reach them)
    var styleEl = document.createElement('style');
    styleEl.textContent =
        '.cl-wrap .cl-cust { margin-top: 18px; }' +
        '.cl-wrap .cl-cust:first-child { margin-top: 0; }' +
        '.cl-wrap .cl-cust-name { font-size: 14px; font-weight: 700; }' +
        '.cl-wrap .cl-dev { padding: 2px 0 2px 8px; font-size: 13px; word-break: break-all; user-select: text; }' +
        '.cl-wrap .cl-empty { font-size: 12px; padding-left: 8px; }' +
        '.cl-wrap .cl-err { font-weight: 600; font-size: 13px; }';
    document.head.appendChild(styleEl);
    self.ctx.clStyle = styleEl;
    
    var root = self.ctx.$container[0];
    var $ = function (s) { return root.querySelector(s); };
    var http = self.ctx.http;
    var list = $('.cl-list');
    var filter = $('.cl-filter');
    var refreshBtn = $('.cl-refresh');
    var data = [];
    var tokens = {};          // device id -> access token

    function errText(e) {
        return (e && e.error && e.error.message) ? e.error.message : 'Ismeretlen hiba';
    }

    function el(tag, cls, text) {
        var e = document.createElement(tag);
        if (cls) { e.className = cls; }
        if (text) { e.textContent = text; }
        return e;
    }

    function getAll(url, cb) {
        var items = [];
        (function next(page) {
            http.get(url + (url.indexOf('?') >= 0 ? '&' : '?') + 'pageSize=100&page=' + page).subscribe(
                function (res) {
                    items = items.concat(res.data || []);
                    if (res.hasNext) { next(page + 1); } else { cb(null, items); }
                },
                function (e) { cb(errText(e)); }
            );
        })(0);
    }

    // loads the access token of every device (5 requests at a time)
    function loadTokens(devs, done) {
        var idx = 0, active = 0, finished = 0;
        if (!devs.length) { done(); return; }

        function step() {
            active--;
            finished++;
            if (finished === devs.length) { done(); } else { launch(); }
        }

        function launch() {
            while (active < 5 && idx < devs.length) {
                var d = devs[idx++];
                active++;
                (function (dev) {
                    http.get('/api/device/' + dev.id.id + '/credentials').subscribe(
                        function (c) {
                            tokens[dev.id.id] = (c.credentialsType === 'ACCESS_TOKEN')
                                ? c.credentialsId
                                : 'nem access token: ' + c.credentialsType;
                            step();
                        },
                        function () { tokens[dev.id.id] = 'a token nem olvasható'; step(); }
                    );
                })(d);
            }
        }
        launch();
    }

    function render() {
        var q = filter.value.trim().toLowerCase();
        list.textContent = '';
        var shown = 0;

        data.forEach(function (grp) {
            var custMatch = !q || grp.name.toLowerCase().indexOf(q) >= 0;
            var devs = grp.devices.filter(function (d) {
                return custMatch || d.name.toLowerCase().indexOf(q) >= 0;
            });
            if (!custMatch && !devs.length) { return; }

            shown++;
            var block = el('div', 'cl-cust');
            block.appendChild(el('div', 'cl-cust-name', grp.name + ' (' + grp.devices.length + ')'));
            if (grp.error) {
                block.appendChild(el('div', 'cl-err', 'Hiba: ' + grp.error));
            } else if (!devs.length) {
                block.appendChild(el('div', 'cl-empty', 'Nincs hozzárendelt gép.'));
            }
            devs.forEach(function (d) {
                var t = tokens[d.id.id];
                  block.appendChild(el('div', 'cl-dev', d.name + (d.label && d.label !== d.name ? ' [' + d.label + ']' : '') + ' (' + (t === undefined ? '...' : t) + ')'));
            });
            list.appendChild(block);
        });

        if (!shown) { list.appendChild(el('div', 'cl-empty', 'Nincs találat.')); }
    }

    function finish() {
        var all = [];
        data.forEach(function (g) { all = all.concat(g.devices); });
        list.textContent = 'Tokenek betöltése...';
        loadTokens(all, render);
    }

    function load() {
        list.textContent = 'Betöltés...';
        data = [];
        tokens = {};

        getAll('/api/customers?sortProperty=title&sortOrder=ASC', function (err, customers) {
            if (err) { list.textContent = ''; list.appendChild(el('div', 'cl-err', 'Hiba: ' + err)); return; }

            var i = 0;
            (function nextCustomer() {
                if (i >= customers.length) { loadUnassigned(); return; }
                var c = customers[i++];
                getAll('/api/customer/' + c.id.id + '/devices?sortProperty=name&sortOrder=ASC', function (e, devs) {
                    data.push({ name: c.title, devices: e ? [] : devs, error: e });
                    nextCustomer();
                });
            })();
        });
    }

    // devices that belong to no customer
    function loadUnassigned() {
        getAll('/api/tenant/devices?sortProperty=name&sortOrder=ASC', function (err, devs) {
            if (!err) {
                var free = devs.filter(function (d) {
                    return !d.customerId || !d.customerId.id || d.customerId.id === NULL_UUID;
                });
                if (free.length) { data.push({ name: 'Nincs ügyfélhez rendelve', devices: free }); }
            }
            finish();
        });
    }

    refreshBtn.addEventListener('click', load);
    filter.addEventListener('input', render);
    load();
};

self.onDestroy = function () {
    if (self.ctx.clStyle && self.ctx.clStyle.parentNode) { self.ctx.clStyle.parentNode.removeChild(self.ctx.clStyle); }
};

